args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?grandfather ?grandfatherLabel WHERE {
  dbr:Musharrif_al-Dawla dbo:father ?father .
  ?father dbo:father ?grandfather .
  OPTIONAL { ?grandfather rdfs:label ?grandfatherLabel . FILTER(lang(?grandfatherLabel) = "en") }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?grandfather ?grandfatherLabel WHERE {
  dbr:Musharrif_al-Dawla (dbo:father|dbp:father|dbo:parent|dbp:parent) ?father .
  ?father (dbo:father|dbp:father|dbo:parent|dbp:parent) ?grandfather .
  OPTIONAL { ?grandfather rdfs:label ?grandfatherLabel . FILTER(lang(?grandfatherLabel) = "en") }
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?p ?o ?olabel WHERE {
  dbr:Musharrif_al-Dawla ?p ?o .
  FILTER(isIRI(?o))
  OPTIONAL { ?o rdfs:label ?olabel . FILTER(lang(?olabel) = "en") }
} ORDER BY ?p

